# Iterative factorial using explicit stack
def factorial_iterative(n):
    result = 1
    while n > 1:
        result *= n
        n -= 1
    return result

# Simulate recursive DFS with explicit stack
def dfs_iterative(graph, start):
    visited = set()
    stack   = [start]          # explicit stack replaces call stack
    order   = []
    while stack:
        node = stack.pop()     # LIFO — mimics recursion
        if node not in visited:
            visited.add(node)
            order.append(node)
            for neighbour in reversed(graph[node]):
                if neighbour not in visited:
                    stack.append(neighbour)
    return order

graph = {0:[1,2], 1:[3], 2:[3], 3:[]}
print(dfs_iterative(graph, 0))  # [0, 1, 3, 2]

# All subsets (power set)
def subsets(nums):
    result = []
    def backtrack(start, current):
        result.append(current[:])   # every partial solution is valid
        for i in range(start, len(nums)):
            current.append(nums[i])          # choose
            backtrack(i + 1, current)        # explore
            current.pop()                    # unchoose
    backtrack(0, [])
    return result

print(subsets([1, 2, 3]))
# [[], [1], [1,2], [1,2,3], [1,3], [2], [2,3], [3]]

# N-Queens — place N queens on NxN board, no two attack each other
def n_queens(n):
    solutions = []
    board = [-1] * n   # board[i] = column of queen in row i

    def is_safe(row, col):
        for r in range(row):
            c = board[r]
            if c == col or abs(c - col) == abs(r - row):
                return False   # same column or diagonal
        return True

    def backtrack(row):
        if row == n:            # all queens placed
            solutions.append(board[:])
            return
        for col in range(n):
            if is_safe(row, col):
                board[row] = col         # place queen
                backtrack(row + 1)       # next row
                board[row] = -1          # remove queen (backtrack)

    backtrack(0)
    return len(solutions)

print(n_queens(4))   # 2
print(n_queens(8))   # 92
